#!/usr/bin/env python3
"""Ross's transcript catch-up: discover all Friend-Message commits on all six
branches, compare full SHAs with published episode files, append new ones."""

import subprocess, re, os, glob, sys, tempfile

SRC = "/tmp/shurik-workspace-ftPdpd"   # read-only fetch source
DEST = "/tmp/ross-main"                # main worktree being edited
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]


def git(*args, cwd=SRC, check=True):
    return subprocess.run(["git", "-C", cwd] + list(args),
                          capture_output=True, text=True, check=check).stdout


def parse_commit(sha):
    """Return (speaker, episode, reply_to, utterance, committer_time) or None."""
    raw = git("show", "-s", "--format=%B%n--END--%n%cI", sha)
    if "Friend-Message: 1" not in raw:
        return None
    body, ts = raw.split("--END--\n", 1)
    ts = ts.strip()
    lines = body.split("\n")
    speaker = episode = reply = None
    reply_idx = None
    for i, l in enumerate(lines):
        if l.startswith("Speaker:"):
            speaker = l.split(":", 1)[1].strip()
        elif l.startswith("Episode:"):
            episode = l.split(":", 1)[1].strip()
        elif l.startswith("Reply-To:"):
            reply = l.split(":", 1)[1].strip()
            reply_idx = i
    if reply_idx is None or episode is None or speaker is None:
        return None
    j = reply_idx + 1
    while j < len(lines) and lines[j].strip() != "":
        j += 1
    if j < len(lines):
        j += 1
    utterance = "\n".join(lines[j:]).strip("\n")
    if not utterance.startswith(speaker + ":"):
        print(f"  !! {sha[:8]} utterance does not start with '{speaker}:'", file=sys.stderr)
        return None
    return dict(sha=sha, speaker=speaker, episode=episode, reply=reply,
                utterance=utterance, ts=ts)


def published_shas():
    out = {}
    for path in glob.glob(os.path.join(DEST, "S*", "E*.md")):
        text = open(path, encoding="utf-8").read()
        for m in re.finditer(r"Source: friend/(\w+) @ ([0-9a-f]{40})", text):
            out[m.group(2)] = (path, m.group(1))
    return out


def frontmatter_for(episode, title="The One With the Next Course",
                    summary="A new Tuesday brings new orders, new rules, and a "
                            "counter full of friends who cannot agree on soup."):
    m = re.match(r"S(\d+)E(\d+)$", episode)
    season, ep = int(m.group(1)), int(m.group(2))
    return (f'---\ntitle: "{title}"\nsummary: "{summary}"\n'
            f"season: {season}\nepisode: {ep}\nstatus: ongoing\n---\n\n{summary}\n")


def main():
    pub = published_shas()
    found = {}
    for br in BRANCHES:
        for sha in git("log", "--format=%H", f"origin/friend/{br}").split():
            rec = parse_commit(sha)
            if rec:
                found[sha] = rec
    missing = [(sha, r) for sha, r in found.items() if sha not in pub]
    missing.sort(key=lambda kv: (kv[1]["ts"], kv[0]))
    print(f"published: {len(pub)}  on branches: {len(found)}  new: {len(missing)}")
    if not missing:
        return
    by_ep = {}
    for sha, r in missing:
        by_ep.setdefault(r["episode"], []).append((sha, r))
    for ep in sorted(by_ep):
        path = os.path.join(DEST, "S01", ep + ".md") if re.match(r"E\d+$", ep) \
            else os.path.join(DEST, ep + ".md")
        # normalise episode ids like S01/E09 or E09 into S01/E09.md
        if ep.startswith("S"):
            parts = ep.split("/")
            path = os.path.join(DEST, parts[0], parts[1] + ".md")
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if not os.path.exists(path):
            open(path, "w", encoding="utf-8").write(frontmatter_for(ep))
            print(f"created {path}")
        text = open(path, encoding="utf-8").read().rstrip("\n")
        chunks = []
        for sha, r in by_ep[ep]:
            chunks.append("**%s** (%s)\n\nSource: friend/%s @ %s\n\n%s\n"
                          % (r["speaker"], r["ts"], r["branch_hint"] if "branch_hint" in r
                             else branch_of(sha), sha, r["utterance"]))
        with open(path, "w", encoding="utf-8") as f:
            f.write(text + "\n\n" + "\n".join(chunks))
        print(f"{ep}: appended {len(by_ep[ep])}")
        for sha, r in by_ep[ep]:
            print(f"   {sha[:8]} {r['speaker']} {r['ts']}")


def branch_of(sha):
    for br in BRANCHES:
        if sha in git("log", "--format=%H", f"origin/friend/{br}"):
            return br
    return "unknown"


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Ross's transcript catch-up: discover all Friend-Message commits on all six
branches, compare full SHAs with published episode files, append new ones."""

import subprocess, re, os, glob, sys

SRC = "/tmp/shurik-workspace-ftPdpd"   # read-only fetch source
DEST = "/tmp/ross-main"                # main worktree being edited
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]


def git(*args, cwd=SRC):
    return subprocess.run(["git", "-C", cwd] + list(args),
                          capture_output=True, text=True, check=True).stdout


def parse_commit(sha):
    raw = git("show", "-s", "--format=%B%n--END--%n%cI", sha)
    if "Friend-Message: 1" not in raw:
        return None
    body, ts = raw.split("--END--\n", 1)
    lines = body.split("\n")
    speaker = episode = reply_idx = None
    for i, l in enumerate(lines):
        if l.startswith("Speaker:"):
            speaker = l.split(":", 1)[1].strip()
        elif l.startswith("Episode:"):
            episode = l.split(":", 1)[1].strip()
        elif l.startswith("Reply-To:"):
            reply_idx = i
    if reply_idx is None or episode is None or speaker is None:
        return None
    j = reply_idx + 1
    while j < len(lines) and lines[j].strip() != "":
        j += 1
    if j < len(lines):
        j += 1
    utterance = "\n".join(lines[j:]).strip("\n")
    if not utterance.startswith(speaker + ":"):
        print(f"  !! {sha[:8]} utterance does not start with '{speaker}:'", file=sys.stderr)
        return None
    return dict(sha=sha, speaker=speaker, episode=episode,
                utterance=utterance, ts=ts.strip())


def episode_path(ep):
    m = re.match(r"(?:S(\d+)/)?E(\d+)$", ep)
    if not m:
        return None
    season = int(m.group(1)) if m.group(1) else 1
    return os.path.join(DEST, f"S{season:02d}", f"E{int(m.group(2)):02d}.md")


def frontmatter(ep, title, summary):
    m = re.match(r"(?:S(\d+)/)?E(\d+)$", ep)
    season = int(m.group(1)) if m.group(1) else 1
    return (f'---\ntitle: "{title}"\nsummary: "{summary}"\n'
            f"season: {season}\nepisode: {int(m.group(2))}\nstatus: ongoing\n"
            f"---\n\n{summary}\n")


def main():
    pub = {}
    for path in glob.glob(os.path.join(DEST, "S*", "E*.md")):
        for m in re.finditer(r"Source: friend/(\w+) @ ([0-9a-f]{40})",
                             open(path, encoding="utf-8").read()):
            pub[m.group(2)] = path

    found, branch_of = {}, {}
    for br in BRANCHES:
        for sha in git("log", "--format=%H", f"origin/friend/{br}").split():
            rec = parse_commit(sha)
            if rec:
                found[sha] = rec
                branch_of[sha] = br

    missing = sorted(((s, r) for s, r in found.items() if s not in pub),
                     key=lambda kv: (kv[1]["ts"], kv[0]))
    print(f"published: {len(pub)}  on branches: {len(found)}  new: {len(missing)}")
    if not missing:
        return 0

    by_ep = {}
    for sha, r in missing:
        by_ep.setdefault(r["episode"], []).append((sha, r))

    created = []
    for ep in sorted(by_ep):
        path = episode_path(ep)
        if path is None:
            print(f"  !! unparsable episode label {ep!r}; skipping", file=sys.stderr)
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if not os.path.exists(path):
            title = "The One With the Next Course"
            summary = ("A new Tuesday brings new orders, new rules, and a counter "
                       "full of friends who cannot agree on soup.")
            with open(path, "w", encoding="utf-8") as f:
                f.write(frontmatter(ep, title, summary))
            created.append(path)
            print(f"created {path}")
        text = open(path, encoding="utf-8").read().rstrip("\n")
        chunks = []
        for sha, r in by_ep[ep]:
            chunks.append("**%s** (%s)\n\nSource: friend/%s @ %s\n\n%s\n"
                          % (r["speaker"], r["ts"], branch_of[sha], sha, r["utterance"]))
            print(f"   {ep}: {sha[:8]} {r['speaker']} {r['ts']}")
        with open(path, "w", encoding="utf-8") as f:
            f.write(text + "\n\n" + "\n".join(chunks))
    print("appended to:", ", ".join(sorted(by_ep)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
